window.LESSON_WORDS = {
  "简陋": {
    "meaning": "简单粗糙，设备或条件不完善。",
    "en": "simple and poorly equipped",
    "paragraph": 1,
    "example": "建国初期，多数国人的住房比较简陋，生活条件也比较落后。"
  },
  "开辟": {
    "meaning": "把原来未充分利用的土地开发出来。",
    "en": "develop previously unused or underused land",
    "paragraph": 1,
    "example": "1960年，政府成立了建屋发展局，开辟土地，兴建了大量的组屋。"
  },
  "兴建": {
    "meaning": "开始建造。",
    "en": "begin construction; build",
    "paragraph": 1,
    "example": "1960年，政府成立了建屋发展局，开辟土地，兴建了大量的组屋。"
  },
  "实施": {
    "meaning": "把计划实际做出来。",
    "en": "put a plan into practice",
    "paragraph": 1,
    "example": "四年后，政府实施“居者有其屋”计划，让国人能够以优惠的价格买到属于自己的房子。"
  },
  "居者有其屋": {
    "meaning": "课文中的住房计划名称，让国人以优惠价格买到自己的房子。",
    "en": "the housing scheme described in the passage, helping citizens buy their own homes at favourable prices",
    "paragraph": 1,
    "example": "四年后，政府实施“居者有其屋”计划，让国人能够以优惠的价格买到属于自己的房子。"
  },
  "优惠": {
    "meaning": "在价格等方面给予较有利的条件。",
    "en": "a benefit, discount or favourable condition",
    "paragraph": 1,
    "example": "四年后，政府实施“居者有其屋”计划，让国人能够以优惠的价格买到属于自己的房子。"
  },
  "所需": {
    "meaning": "所需要的东西或条件。",
    "en": "what is needed",
    "paragraph": 2,
    "example": "为了满足人民的生活所需，增强社区居民的凝聚力，政府在兴建组屋时也重视市镇的规划。"
  },
  "凝聚力": {
    "meaning": "使居民彼此联系、愿意团结合作的力量。",
    "en": "the bond that unites people and encourages cooperation",
    "paragraph": 2,
    "example": "为了满足人民的生活所需，增强社区居民的凝聚力，政府在兴建组屋时也重视市镇的规划。"
  },
  "规划": {
    "meaning": "对设施、空间等作整体安排。",
    "en": "plan the overall arrangement of spaces or facilities",
    "paragraph": 2,
    "example": "为了满足人民的生活所需，增强社区居民的凝聚力，政府在兴建组屋时也重视市镇的规划。"
  },
  "邻里中心": {
    "meaning": "为附近居民提供商店和生活服务的地方。",
    "en": "a neighbourhood centre with shops and everyday services",
    "paragraph": 2,
    "example": "市镇里一般都有邻里中心、游乐场、图书馆、公园、小贩中心、宗教场所、市镇理事会、民众俱乐部、综合诊疗所等。"
  },
  "宗教": {
    "meaning": "有关信仰的思想和活动。",
    "en": "religious beliefs and practices",
    "paragraph": 2,
    "example": "市镇里一般都有邻里中心、游乐场、图书馆、公园、小贩中心、宗教场所、市镇理事会、民众俱乐部、综合诊疗所等。"
  },
  "综合": {
    "meaning": "把几个方面结合在一起。",
    "en": "combine several different aspects",
    "paragraph": 2,
    "example": "市镇里一般都有邻里中心、游乐场、图书馆、公园、小贩中心、宗教场所、市镇理事会、民众俱乐部、综合诊疗所等。"
  },
  "综合诊疗所": {
    "meaning": "提供多种基层医疗服务的诊所。",
    "en": "a polyclinic offering a range of primary healthcare services",
    "paragraph": 2,
    "example": "市镇里一般都有邻里中心、游乐场、图书馆、公园、小贩中心、宗教场所、市镇理事会、民众俱乐部、综合诊疗所等。"
  },
  "经济": {
    "meaning": "与生产、贸易、消费等有关的活动和状况。",
    "en": "activities and conditions involving production, trade and consumption",
    "paragraph": 3,
    "example": "随着新加坡经济的蓬勃发展，国人的生活越来越富裕，生活水平也提高了。"
  },
  "蓬勃": {
    "meaning": "兴盛、有活力的样子。",
    "en": "thriving; full of growth and energy",
    "paragraph": 3,
    "example": "随着新加坡经济的蓬勃发展，国人的生活越来越富裕，生活水平也提高了。"
  },
  "富裕": {
    "meaning": "财物充足，生活宽裕。",
    "en": "well-off; having sufficient wealth",
    "paragraph": 3,
    "example": "随着新加坡经济的蓬勃发展，国人的生活越来越富裕，生活水平也提高了。"
  },
  "与时俱进": {
    "meaning": "随着时代的发展不断进步。",
    "en": "keep developing and improving with the times",
    "paragraph": 3,
    "example": "为了与时俱进，建屋发展局给组屋的设计注入更多活力，推出了许多设计新颖、造型美观的新组屋。"
  },
  "注入": {
    "meaning": "这里指加入，使设计更有活力。",
    "en": "here, introduce something that adds energy to a design",
    "paragraph": 3,
    "example": "为了与时俱进，建屋发展局给组屋的设计注入更多活力，推出了许多设计新颖、造型美观的新组屋。"
  },
  "新颖": {
    "meaning": "新鲜而有特色，不落俗套。",
    "en": "fresh and original",
    "paragraph": 3,
    "example": "为了与时俱进，建屋发展局给组屋的设计注入更多活力，推出了许多设计新颖、造型美观的新组屋。"
  },
  "美观": {
    "meaning": "看起来漂亮。",
    "en": "pleasing in appearance",
    "paragraph": 3,
    "example": "为了与时俱进，建屋发展局给组屋的设计注入更多活力，推出了许多设计新颖、造型美观的新组屋。"
  },
  "变迁": {
    "meaning": "随着时间推移而发生变化。",
    "en": "changes that take place over time",
    "paragraph": 4,
    "example": "时代不断变迁，建屋发展局在设计组屋时越来越关注环保和人口老化等问题。"
  },
  "环保": {
    "meaning": "环境保护。",
    "en": "environmental protection",
    "paragraph": 4,
    "example": "时代不断变迁，建屋发展局在设计组屋时越来越关注环保和人口老化等问题。"
  },
  "人口老化": {
    "meaning": "人口中老年人的比例增加。",
    "en": "population ageing; a growing proportion of older people",
    "paragraph": 4,
    "example": "时代不断变迁，建屋发展局在设计组屋时越来越关注环保和人口老化等问题。"
  },
  "交流": {
    "meaning": "彼此沟通、分享想法或一起活动。",
    "en": "communicate and exchange ideas, experiences or feelings",
    "paragraph": 4,
    "example": "组屋区里为居民提供了更多的交流空间，环保和无障碍设施也越来越完善。"
  },
  "障碍": {
    "meaning": "使行动或事情难以顺利进行的阻碍。",
    "en": "an obstacle that makes movement or progress difficult",
    "paragraph": 4,
    "example": "组屋区里为居民提供了更多的交流空间，环保和无障碍设施也越来越完善。"
  },
  "无障碍": {
    "meaning": "通过环境与设施设计，减少行动不便者遇到的阻碍。",
    "en": "barrier-free; designed to improve access for people with mobility difficulties",
    "paragraph": 4,
    "example": "组屋区里为居民提供了更多的交流空间，环保和无障碍设施也越来越完善。"
  },
  "完善": {
    "meaning": "这里指设施越来越齐备，使用起来更合适。",
    "en": "here, make facilities more complete and suitable for use",
    "paragraph": 4,
    "example": "组屋区里为居民提供了更多的交流空间，环保和无障碍设施也越来越完善。"
  },
  "宜居": {
    "meaning": "适合人们居住。",
    "en": "suitable and pleasant to live in",
    "paragraph": 4,
    "example": ""
  },
  "驰名": {
    "meaning": "名声传播得很远。",
    "en": "widely renowned",
    "paragraph": 5,
    "example": "如今，新加坡的组屋驰名海内外，市镇规划和组屋设计也屡次得奖，获得许多荣誉。"
  },
  "海内外": {
    "meaning": "国内和国外。",
    "en": "at home and abroad",
    "paragraph": 5,
    "example": "如今，新加坡的组屋驰名海内外，市镇规划和组屋设计也屡次得奖，获得许多荣誉。"
  },
  "屡次": {
    "meaning": "多次，一次又一次。",
    "en": "repeatedly; many times",
    "paragraph": 5,
    "example": "如今，新加坡的组屋驰名海内外，市镇规划和组屋设计也屡次得奖，获得许多荣誉。"
  },
  "荣誉": {
    "meaning": "因受到肯定而获得的光荣或好名声。",
    "en": "honour or recognition for an achievement",
    "paragraph": 5,
    "example": "如今，新加坡的组屋驰名海内外，市镇规划和组屋设计也屡次得奖，获得许多荣誉。"
  },
  "标志": {
    "meaning": "能使人认出或联想到某事物的代表。",
    "en": "a symbol or feature that represents something",
    "paragraph": 5,
    "example": "组屋已是新加坡的重要标志之一，也成为新加坡一道美丽的风景线。"
  }
};
window.WORD_ALIASES = {};
window.HWT_WORD_CONTEXT = ()=>({lessonId:"s2u5l1",lessonTitle:"组屋，新加坡美丽的风景线",grade:2,unit:5,paragraphs:window.LESSON.paragraphs});
window.HWT_WORD_LEXICON=()=>window.LESSON_WORDS;

/* Hosted assets are kept below the per-file size limit; the user gets one ZIP. */
(()=>{const status=document.querySelector('#packStatus');
const hash=async data=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(x=>x.toString(16).padStart(2,'0')).join('');
async function download(manifest,button){button.disabled=true;let url;try{
 status.textContent='正在准备整套配套……';
 const response=await fetch('downloads/'+manifest);if(!response.ok)throw Error('清单暂时无法读取');const m=await response.json();
 const parts=[];let total=0;
 for(let i=0;i<m.parts.length;i++){const p=m.parts[i];status.textContent=`正在下载 ${i+1} / ${m.parts.length}，请稍候……`;const r=await fetch('downloads/'+p.file);if(!r.ok)throw Error('部分资源下载失败');const a=await r.arrayBuffer();if(a.byteLength!==p.bytes||await hash(a)!==p.sha256)throw Error('文件校验未通过，请重试');parts.push(a);total+=a.byteLength;}
 if(total!==m.bytes)throw Error('文件不完整');const blob=new Blob(parts,{type:m.mime||'application/zip'});if(await hash(await blob.arrayBuffer())!==m.sha256)throw Error('整套文件校验未通过');url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=m.name;document.body.appendChild(a);a.click();a.remove();status.textContent='文件已准备好，请在浏览器下载列表中保存。ZIP请先解压再使用。';setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch(e){status.textContent='下载未完成：'+e.message+'。可重试，或分别下载上方的PPT、教师方案和互动HTML。';if(url)URL.revokeObjectURL(url)}finally{button.disabled=false}}
document.querySelectorAll('[data-pack]').forEach(b=>b.onclick=()=>download(b.dataset.pack+'-manifest.json',b));
})();

/* Reusable textbook lesson engine. Content and stable question IDs live in content.js. */
(()=>{'use strict';
const L=window.LESSON,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(L.wordEnglishVisible)document.body.classList.add('word-support-visible');
const KEY=window.LESSON_STORAGE_KEY||'huawentong-lesson-'+L.id+'-v1', cn=['一','二','三','四','五','六','七','八','九','十','十一','十二','十三','十四','十五','十六','十七','十八','十九'];
const empty=()=>({schema:'huawentong-lesson-v1',lessonId:L.id,contentVersion:L.version,sequenceVersion:L.sequenceVersion,sources:{},position:{view:'read',p:1,task:0},identity:{name:'',class:'',number:''},answers:{}});
let state=empty(),selected=null,persistFailed=false;try{const v=JSON.parse(localStorage.getItem(KEY));if(v?.lessonId===L.id&&v?.schema===state.schema)state={...state,...v,sequenceVersion:v.sequenceVersion||1}}catch{}
state.answers=state.answers||{};state.identity=state.identity||{name:'',class:'',number:''};
if(state.sequenceVersion!==L.sequenceVersion){if(Object.keys(state.answers).length){state.legacyVersions=state.legacyVersions||[];state.legacyVersions.push({version:state.contentVersion,answers:JSON.parse(JSON.stringify(state.answers))});const oldId=L.legacyOrder?.[state.position.task];const target=L.routeAliases?.[oldId]||oldId;state.position.task=Math.max(0,L.tasks.findIndex(t=>t.id===target));}state.sequenceVersion=L.sequenceVersion;state.contentVersion=L.version;}
state.sources=state.sources||{};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));persistFailed=false}catch{persistFailed=true}const n=$('#saveState');if(n)n.textContent=persistFailed?'保存失败，请导出记录':'已保存';window.dispatchEvent(new CustomEvent('hwt:lesson-saved'));};
const a=id=>state.answers[id]||(state.answers[id]={fields:{},choices:{},evidence:{},attempts:[],hintCount:0,revision:'',points:[],unlocked:false});
const allFields=t=>[...(t.fields||[]),...(t.answerTable?.fields||[])];
function fieldInput(f,x,label=f.label,limit=5000){return f.type==='select'?`<select id="field-${esc(f.id)}" data-field="${esc(f.id)}" aria-label="${esc(label)}"><option value="">请选择</option>${(f.options||[]).map(v=>`<option value="${esc(v)}" ${x.fields[f.id]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<textarea id="field-${esc(f.id)}" data-field="${esc(f.id)}" rows="3" maxlength="${limit}" aria-label="${esc(label)}" placeholder="${esc(f.placeholder||'')}">${esc(x.fields[f.id]||'')}</textarea>`}
const task=()=>L.tasks[Math.max(0,Math.min(L.tasks.length-1,state.position.task))];
function kw(s,words=[]){let result=esc(s);[...words].sort((a,b)=>b.length-a.length).forEach(w=>result=result.split(esc(w)).join('<span class="key">'+esc(w)+'</span>'));return result}
function panel(n){if(L.panelImages?.[n-1]){const path=L.panelImages[n-1],src=window.LESSON_ASSETS?.[path]||path,r=L.panelRects[n-1];return `<div class="panel panel-direct"><img src="${esc(src)}" alt="原有漫画第${n}格" width="${r[2]}" height="${r[3]}" loading="eager" decoding="async"></div>`}const r=L.panelRects[n-1],sheet=L.panelSheets?.[n-1]||Math.ceil(n/10),src=window.LESSON_ASSETS?.['comic'+sheet]||'assets/comic'+sheet+'.png';return `<div class="panel" style="aspect-ratio:${r[2]}/${r[3]}"><img src="${src}" alt="原有漫画第${n}格" style="width:${1024/r[2]*100}%;left:${-r[0]/r[2]*100}%;top:${-r[1]/r[3]*100}%" loading="lazy"></div>`}
const pName=p=>'第'+(cn[p-1]||p)+(L.unitNoun||'段');
const sentences=p=>L.paragraphs[p-1].match(/[^。！？]+[。！？][”’]?|[^。！？]+$/g)||[L.paragraphs[p-1]];
function marked(s){const aliases=window.WORD_ALIASES||{},words=[...Object.keys(window.LESSON_WORDS),...Object.keys(aliases)].filter(w=>s.includes(w)).sort((a,b)=>b.length-a.length);if(!words.length)return esc(s);const re=new RegExp('('+words.join('|')+')','g');return s.split(re).map(v=>window.LESSON_WORDS[aliases[v]||v]?`<span class="word" role="button" tabindex="0" data-word="${esc(aliases[v]||v)}">${esc(v)}</span>`:esc(v)).join('')}
function figure(p){const f=L.figures?.[p];if(!f)return '';let body='';
const sourceImage=()=>{const r=f.rect;if(f.directSrc){const src=window.LESSON_ASSETS?.[f.directSrc]||f.directSrc;return `<div class="panel panel-direct"><img src="${esc(src)}" alt="${esc(f.alt||f.title)}" width="${r[2]}" height="${r[3]}" loading="eager" decoding="async"></div>`}const src=window.LESSON_ASSETS?.[f.src]||f.src;return `<div class="figure-crop" style="aspect-ratio:${r[2]}/${r[3]}"><img src="${esc(src)}" alt="${esc(f.alt||f.title)}" style="width:${f.imageWidth/r[2]*100}%;left:${-r[0]/r[2]*100}%;top:${-r[1]/r[3]*100}%" loading="lazy"></div>`};
if(f.kind==='sourceImage'||f.kind==='diagram'){body=sourceImage();if(f.rows)body+='<div class="diagram-text">'+f.rows.map(r=>'<p><strong>'+esc(r[0])+'</strong>：'+esc(r[1])+'</p>').join('')+'</div>';return '<figure class="data-figure"><figcaption>'+esc(f.title)+'</figcaption>'+body+'<p class="data-note">'+esc(f.note)+'</p></figure>';}
if(f.kind==='pie'){const colors=['#337951','#7f8d72','#efd967','#b0c64f','#cc635f'];let a=-Math.PI/2;body='<svg viewBox="0 0 200 200" role="img" aria-label="'+esc(f.title)+'">';f.rows.forEach((r,i)=>{const next=a+Number(r[1])/100*Math.PI*2;body+=`<path d="M100 100 L${100+88*Math.cos(a)} ${100+88*Math.sin(a)} A88 88 0 ${next-a>Math.PI?1:0} 1 ${100+88*Math.cos(next)} ${100+88*Math.sin(next)} Z" fill="${colors[i]}" stroke="white" stroke-width="1.5"/>`;a=next});body+='</svg><table><thead><tr><th>类别</th><th>比例</th></tr></thead><tbody>'+f.rows.map((r,i)=>'<tr><td><span class="chart-key" style="background:'+colors[i]+'"></span>'+esc(r[0])+'</td><td>'+esc(r[1])+'%</td></tr>').join('')+'</tbody></table>';return '<figure class="data-figure"><figcaption>'+esc(f.title)+'</figcaption>'+body+'<p class="data-note">'+esc(f.note)+'</p></figure>';}
if(f.kind==='table'){body='<table><thead><tr>'+f.headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+f.rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}else{const max=f.kind==='share'?100:f.kind==='bars'?30:180;body=f.rows.map((r,i)=>'<div class="bar-row"><span>'+esc(r[0])+'</span><span class="bar-track" aria-hidden="true"><span class="bar-fill '+(f.kind==='trend'&&i===f.rows.length-1?'target-bar':'')+'" style="width:'+(Number(r[1])/max*100)+'%"></span></span><strong>'+esc(r[1])+(f.unit==='%'?'%':'')+'</strong></div>').join('');if(f.unit!=='%')body+='<p>单位：'+esc(f.unit)+'／人／日</p>'}return '<figure class="data-figure"><figcaption>'+esc(f.title)+'</figcaption>'+body+'<p class="data-note">'+esc(f.note)+'</p></figure>'}
function paragraph(p,selectable){return `<section class="source-paragraph" id="p${p}"><h3>${pName(p)}${L.paragraphLabels?.[p-1]?" · "+esc(L.paragraphLabels[p-1]):""}</h3><div class="source-text">${sentences(p).map((s,i)=>selectable?`<span class="sentence" tabindex="0" role="button" data-p="${p}" data-i="${i}" draggable="true">${L.wordEnglishVisible?marked(s):esc(s)}</span>`:marked(s)).join('')}</div>${figure(p)}</section>`}
function range(t){if(t.range.length===2)return Array.from({length:t.range[1]-t.range[0]+1},(_,i)=>t.range[0]+i);return t.range}
function route(){let h=location.hash.slice(1);if(h.startsWith('task-'))h='task-'+(L.routeAliases?.[h.slice(5)]||h.slice(5));if(h==='read')state.position={...state.position,view:'read'};if(/^paragraph-\d+$/.test(h)){state.position.view='read';state.position.p=Math.max(1,Math.min(L.paragraphs.length,+h.split('-')[1]))}if(/^lesson[123]$/.test(h)){state.position.view='task';state.position.task=L.tasks.findIndex(t=>t.lesson===+h.slice(-1))}const ti=L.tasks.findIndex(t=>'task-'+t.id===h);if(ti>=0){state.position.view='task';state.position.task=ti}if(h==='review')state.position.view='review';render();save();if(h==='words')window.WordBook.open()}
function go(hash){window.speechSynthesis?.cancel();selected=null;if(location.hash.slice(1)===hash)route();else location.hash=hash;window.scrollTo?.({top:0,behavior:'instant'})}
function render(){const view=state.position.view;$('#readTask').hidden=view==='review';$('#review').hidden=view!=='review';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(view==='task'?'lesson'+task().lesson:view)));if(view==='review'){review();return}if(view==='read')read();else activity()}
